do $$begin if not exists(select 1 from public.profiles where email='admin@demo.tkd') then raise exception 'Auth profile trigger failed';end if;if not exists(select 1 from public.organization_members where role='SUPER_ADMIN') then raise exception 'Cloud seed membership failed';end if;if(select count(*)from pg_tables where schemaname='public' and rowsecurity)<>29 then raise exception 'Unexpected RLS table count';end if;if exists(select 1 from information_schema.columns where table_schema='public' and table_name='public_match_display' and column_name in('date_of_birth','contact_email','token_hash')) then raise exception 'Public view exposes restricted data';end if;end$$;
